      reasonsMr.push(`${profile.state} \u0930\u093E\u091C\u094D\u092F\u093E\u091A\u0947 \u0930\u0939\u093F\u0935\u093E\u0938\u0940 \u0905\u0938\u0932\u094D\u092F\u093E\u0928\u0947 \u0905\u0927\u093F\u0935\u093E\u0938 \u092A\u093E\u0924\u094D\u0930\u0924\u093E \u092A\u0942\u0930\u094D\u0923.`);
